enum FynkelQueryKind {
  /// entity -> one SnapshotTransformRecord (0 records if unknown).
  FYNKEL_QUERY_TRANSFORM(1),

  /// entity -> u64 handles of its children, deterministic order.
  FYNKEL_QUERY_CHILDREN(2),

  /// entity -> one u64: parent handle or 0.
  FYNKEL_QUERY_PARENT(3),

  /// entity -> one Name record (0 records if none).
  FYNKEL_QUERY_NAME(4),

  /// (no entity) -> u64 handles of every live entity, slot order.
  FYNKEL_QUERY_ALL_ENTITIES(5),

  /// entity -> one framed record per native component it has, id order:
  /// a ComponentHeader { component, size } then the component's body
  /// (0 records if unknown).
  FYNKEL_QUERY_COMPONENTS(6),

  /// entity -> one BodyStateRecord (0 records without a RigidBody).
  FYNKEL_QUERY_BODY(7),

  /// (no entity) -> one EntityInfoRecord { entity, parent, name, layer,
  /// tags, active } per live entity, slot order: the hierarchy, the names,
  /// the tags and the active flags in one call.
  FYNKEL_QUERY_ENTITIES(8),

  /// entity -> one CharacterStateRecord { entity, grounded, sliding,
  /// velocity } (0 records without a CharacterController) (M3-09).
  FYNKEL_QUERY_CHARACTER(9),

  /// (no entity) -> one SystemTimeRecord { system, entities, micros } per
  /// SystemKind: the last step's per-phase wall time (M3-10).
  FYNKEL_QUERY_SYSTEMS(10),

  /// entity -> one AnimatorStateRecord { entity, time, duration, speed,
  /// fade_remaining, playing, looping, clip } (0 records without an
  /// Animator) (M3-19).
  FYNKEL_QUERY_ANIMATOR(11),

  /// entity -> one AudioStateRecord { entity, playing, paused, time,
  /// duration, volume, pitch, looping, clip, bus, voice } (0 records
  /// without an AudioSource) (M3-11).
  FYNKEL_QUERY_AUDIO(12),

  /// (no entity) -> one AudioStatsRecord: the audio engine's device,
  /// voices and counters (M3-11).
  FYNKEL_QUERY_AUDIO_STATS(13);

  final int value;
  const FynkelQueryKind(this.value);

  static FynkelQueryKind fromValue(int value) => switch (value) {
    1 => FYNKEL_QUERY_TRANSFORM,
    2 => FYNKEL_QUERY_CHILDREN,
    3 => FYNKEL_QUERY_PARENT,
    4 => FYNKEL_QUERY_NAME,
    5 => FYNKEL_QUERY_ALL_ENTITIES,
    6 => FYNKEL_QUERY_COMPONENTS,
    7 => FYNKEL_QUERY_BODY,
    8 => FYNKEL_QUERY_ENTITIES,
    9 => FYNKEL_QUERY_CHARACTER,
    10 => FYNKEL_QUERY_SYSTEMS,
    11 => FYNKEL_QUERY_ANIMATOR,
    12 => FYNKEL_QUERY_AUDIO,
    13 => FYNKEL_QUERY_AUDIO_STATS,
    _ => throw ArgumentError('Unknown value for FynkelQueryKind: $value'),
  };
}

/// ---- Buffer header ------------------------------------------------------
final class FynkelBufferHeader extends ffi.Struct {
  /// FYNKEL_BUFFER_MAGIC
  @ffi.Uint32()
  external int magic;

  /// FYNKEL_ABI_VERSION
  @ffi.Uint16()
  external int version;

  /// FynkelBufferKind
  @ffi.Uint16()
  external int kind;

  @ffi.Uint32()
  external int record_count;

  /// whole buffer incl. header and tail
  @ffi.Uint32()
  external int byte_length;

  /// offset where the string tail starts
  @ffi.Uint32()
  external int records_end;

  /// query responses echo the request id
  @ffi.Uint32()
  external int request_id;
}

/// ---- Call structs -------------------------------------------------------
final class FynkelBufferView extends ffi.Struct {
  /// NULL when length == 0
  external ffi.Pointer<ffi.Uint8> data;

  @ffi.Uint32()
  external int length;
}

final class FynkelWorldDesc extends ffi.Struct {
  /// 1..255; 0 = default (1)
  @ffi.Uint8()
  external int world_id;

  @ffi.Array.multi([3])
  external ffi.Array<ffi.Uint8> reserved;

  /// 0 = default 1/60
  @ffi.Float()
  external double fixed_dt_seconds;

  /// 0 = default 4
  @ffi.Uint32()
  external int max_steps_per_frame;

  /// 0 = default 0.25
  @ffi.Float()
  external double max_frame_dt_seconds;

  /// reserved
  @ffi.Uint32()
  external int flags;
}

final class FynkelFramePlan extends ffi.Struct {
  /// fixed ticks to run this frame
  @ffi.Uint32()
  external int steps;

  /// > 0: MissedDeadline recorded
  @ffi.Float()
  external double dropped_seconds;

  /// frame dt exceeded max_frame_dt
  @ffi.Uint32()
  external int clamped;

  /// interpolation factor after the steps
  @ffi.Float()
  external double alpha;
}

final class FynkelSubmitResult extends ffi.Struct {
  /// staged (simulation) or applied (presentation)
  @ffi.Uint32()
  external int accepted;

  /// diagnostics describe each one
  @ffi.Uint32()
  external int rejected;
}

final class FynkelStepResult extends ffi.Struct {
  /// tick number after the step
  @ffi.Uint64()
  external int tick;

  @ffi.Uint32()
  external int commands_applied;

  @ffi.Uint32()
  external int commands_rejected;

  @ffi.Uint32()
  external int snapshot_records;

  /// pending in the general lane
  @ffi.Uint32()
  external int event_records;

  @ffi.Uint32()
  external int diagnostic_records;

  @ffi.Uint32()
  external int live_entities;
}

final class FynkelQueryDesc extends ffi.Struct {
  /// FynkelQueryKind
  @ffi.Uint32()
  external int kind;

  /// echoed in the response header
  @ffi.Uint32()
  external int request_id;

  /// subject, per kind
  @FynkelEntity()
  external int entity;
}

/// Bridge statistics since world creation (blueprint §5.7, M1 gate).
final class FynkelWorldStats extends ffi.Struct {
  @ffi.Uint64()
  external int tick;

  @ffi.Uint64()
  external int frame;

  @ffi.Uint64()
  external int submit_calls;

  @ffi.Uint64()
  external int step_calls;

  @ffi.Uint64()
  external int query_calls;

  /// command bytes received
  @ffi.Uint64()
  external int bytes_in;

  /// snapshot+event+diagnostic+query bytes produced
  @ffi.Uint64()
  external int bytes_out;

  @ffi.Uint32()
  external int live_entities;

  @ffi.Uint32()
  external int subscriptions;

  @ffi.Uint32()
  external int staged_commands;

  @ffi.Uint32()
  external int poisoned;

  /// the last step's snapshot
  @ffi.Uint64()
  external int snapshot_bytes;

  /// the largest snapshot so far
  @ffi.Uint64()
  external int snapshot_peak_bytes;

  /// fynkel_world_set_snapshot_budget; 0 = none
  @ffi.Uint32()
  external int snapshot_budget;

  @ffi.Uint32()
  external int reserved;

  /// Rust heap in use, the whole engine's
  @ffi.Uint64()
  external int native_bytes;

  /// process resident set; 0 where not reported
  @ffi.Uint64()
  external int resident_bytes;

  /// CPU bytes of the resident assets
  @ffi.Uint64()
  external int residency_bytes;
}

final class FynkelProjectionInfo extends ffi.Struct {
  /// the entity rendered from; 0 = no camera
  @ffi.Uint64()
  external int camera;

  /// anchors projected
  @ffi.Uint32()
  external int projected;

  /// anchors beyond the bound
  @ffi.Uint32()
  external int dropped;
}

/// Runtime prefab instantiation (M3-08b, blueprint §6 item 12). Spawns,
/// now, an anchor entity named `name_utf8` (empty: the prefab's name) with
/// the given local transform under `parent` (0 = root), and the cooked
/// prefab `prefab_id_utf8` (36-char UUID text) as the anchor's children —
/// the shape a scene instance expands to. The prefab comes from the cache
/// the last successful load opened (FYNKEL_STATUS_LOAD_FAILED before any);
/// its closure is retained with the scene's. Components go through the
/// command path; the anchor and the entities are in the report:
/// {"ok", "instance": {"prefab", "name", "path", "anchor": u64,
/// "entities": n, "rejectedComponents", "assets", "behaviours": [...]},
/// "diagnostics": [...]}. FYNKEL_STATUS_LOAD_FAILED when the prefab is not
/// in the cache, does not decode (recook) or `parent` is not live (the
/// world is unchanged).
final class FynkelInstantiateDesc extends ffi.Struct {
  external ffi.Pointer<ffi.Uint8> prefab_id_utf8;

  @ffi.Uint32()
  external int prefab_id_len;

  /// NULL with name_len 0 for none
  external ffi.Pointer<ffi.Uint8> name_utf8;

  @ffi.Uint32()
  external int name_len;

  /// 0: a root
  @FynkelEntity()
  external int parent;

  @ffi.Array.multi([3])
  external ffi.Array<ffi.Float> position;

  /// x, y, z, w
  @ffi.Array.multi([4])
  external ffi.Array<ffi.Float> rotation;

  @ffi.Array.multi([3])
  external ffi.Array<ffi.Float> scale;
}

const int FYNKEL_ABI_VERSION = 1;

const int FYNKEL_BUFFER_MAGIC = 1263425862;

const int FYNKEL_BUFFER_HEADER_SIZE = 24;

const int FYNKEL_MAX_PROJECTION_ANCHORS = 64;

const int FYNKEL_PROJECTED_IN_FRONT = 1;

const int FYNKEL_PROJECTED_ON_SCREEN = 2;

const int FYNKEL_PROJECTED_OCCLUDED = 4;

const int FYNKEL_PROJECTED_MISSING = 8;

const int FYNKEL_PROJECTED_NO_CAMERA = 16;

const int FYNKEL_PROJECTED_DROPPED = 32;

const int FYNKEL_LOAD_ADDITIVE = 1;
